{
  "verses": [
    {
      "text_ar": "وقال الله: لنصنع الإنسان على صورتنا، كشبهنا، وخلق الله الإنسان على صورته.",
      "chapter": 1,
      "verse": 1
    },
    {
      "text_ar": "وجبل الله الإنسان من التراب، ونفخ في أنفه نسمة الحياة، فأصبح الإنسان نفسًا حيةً ناطقةً.",
      "chapter": 1,
      "verse": 2
    },
    {
      "text_ar": "وقال الرب: ليس جيدًا أن يكون الإنسان وحدَهُ؛ فأصنع له معينًا.",
      "chapter": 1,
      "verse": 3
    },
    {
      "text_ar": "فأوقع الرب الإله نومًا عميقًا على آدم، فنام، فأخذ إحدى أضلاعه وكساها لحمًا، وشكّلها وأحضرها إلى آدم، فاستيقظ آدم من نومه وإذا امرأة تقف أمامه.",
      "chapter": 1,
      "verse": 4
    },
    {
      "text_ar": "فقال: هذه عظم من عظامي ولحم من لحمي، وهذه تدعى امرأة لأنها من امرئ أُخذت؛ وسمى آدم امرأته حواء لأنها أم كل حي.",
      "chapter": 1,
      "verse": 5
    },
    {
      "text_ar": "وباركهما الله ودعا اسميهما آدم وحواء في اليوم الذي خلقهما فيه، وقال الرب الإله: أثمرا وتكاثرا واملأا الأرض.",
      "chapter": 1,
      "verse": 6
    },
    {
      "text_ar": "وأخذ الرب الإله آدم وزوجته، ووضعهما في جنة عدن ليفلحاها ويحفظاها؛ وأمرهما قائلاً: من كل شجرة في الجنة تأكلون، وأما شجرة معرفة الخير والشر فلا تأكلا منها، لأنكما يوم تأكلان منها تموتان موتًا.",
      "chapter": 1,
      "verse": 7
    },
    {
      "text_ar": "ولما باركهما الله وأوصاهما، انصرف عنهما، وسكن آدم وزوجته في الجنة بحسب الوصية التي أمرهما بها الرب.",
      "chapter": 1,
      "verse": 8
    },
    {
      "text_ar": "وجاءت الحية، التي خلقها الله معهما على الأرض، إليهما لتغويهما على تعدي وصية الله التي أمر بها.",
      "chapter": 1,
      "verse": 9
    },
    {
      "text_ar": "فأغرت الحية المرأة وأقنعتها بأن تأكل من شجرة المعرفة، وأصغت المرأة لصوت الحية، وتعدت كلام الله، فأخذت من شجرة معرفة الخير والشر وأكلت، وأخذت منها وأعطت لزوجها أيضًا فأكل.",
      "chapter": 1,
      "verse": 10
    }
  ],
  "book_code": "JASHER"
}
